// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _test(uint256 val) internal {
        vm.assume(val != 0);
        try c.SetMinSum(val) {} catch { return; }
        uint256 m;
        try c.MinSum() returns (uint256 __r) { m = __r; } catch { return; }
        assertTrue(m == val);
    }

    function testFuzz_test(uint256 val) public {
        _test(val);
    }

    receive() external payable {}
}
